widget.prelude:
def in_discs(p):
    x, y = p
    return min((x + 1.5) ** 2 + y ** 2, (x - 1.5) ** 2 + y ** 2) <= 1 + 1e-12

def in_ellipse(p):
    x, y = p
    return x * x / 4 + y * y <= 1 + 1e-12

widget.solution:
def mix(a, b, theta):
    return [theta * x + (1 - theta) * y for x, y in zip(a, b)]


def in_capped_simplex(w, cap, tol=1e-9):
    if abs(sum(w) - 1) > tol:
        return False
    return all(-tol <= x <= cap + tol for x in w)


def segment_stays_in(member, a, b, n):
    return all(member(mix(a, b, k / n)) for k in range(n + 1))
